function textField(parent,key,value,change,options={}){const wrap=node('label');wrap.className=options.wide?'field wide-field':'field';wrap.append(node('span',t(key)));const input=node(options.short?'input':'textarea');input.value=value;input.maxLength=options.short?180:2000;if(!options.short)input.rows=2;input.addEventListener('input',()=>change(input.value));wrap.append(input);parent.append(wrap);return input;}
