function preview(data){if(!data)return;previewData=data;$('previewImage').src=data.data;$('previewImage').alt=data.label;$('previewImage').hidden=false;$('copyFallback').hidden=true;$('previewDownload').hidden=false;$('previewDialog').showModal();}
async function readImage(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024**2)throw Error(t('imageError'));const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(img.naturalWidth*img.naturalHeight>60000000)throw Error(t('imageError'));const c=document.createElement('canvas'),scale=Math.min(1,1280/img.naturalWidth,1280/img.naturalHeight);c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);let quality=.88,data=c.toDataURL('image/jpeg',quality);while(data.length>1500000&&quality>.4){quality-=.12;data=c.toDataURL('image/jpeg',quality);}if(data.length>1500000)throw Error(t('imageError'));return {data,label:file.name.slice(0,180)};}finally{URL.revokeObjectURL(url);}}
async function attach(file,shotId=null){if(imageBusy)return;imageBusy=true;const projectId=state.id;try{const data=await readImage(file);if(state.id!==projectId)return;if(shotId){const shot=state.shots.find(s=>s.id===shotId);if(!shot)return;shot.result=data;}else state.reference=data;persist();renderReference();renderShots();computed();}catch(e){status('imageError');}finally{imageBusy=false;}}
