function renderReference(){const img=$('referenceImage');img.hidden=!state.reference;$('referenceEmpty').hidden=!!state.reference;$('referenceLarge').disabled=$('referenceRemove').disabled=!state.reference;if(state.reference){img.src=state.reference.data;img.alt=state.reference.label;}else img.removeAttribute('src');}
