async function copy(value){try{await navigator.clipboard.writeText(value);status('copied');}catch{const area=node('textarea');area.value=value;area.style.cssText='position:fixed;left:0;top:0;opacity:.01';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(ok)status('copied');else{$('previewImage').hidden=true;$('previewDownload').hidden=true;$('copyFallback').hidden=false;$('copyFallback').value=value;$('previewDialog').showModal();$('copyFallback').select();}}}
function readySheet(){if(state.shots.some(s=>['image','video'].some(k=>!extensions.visible(s,k).ready))){status('copyBlocked');return false;}return true;}
function promptSheet(){return 'ARTOFTOMWORKS SCENE DNA '+VERSION+'\n'+state.title+'\n\n'+state.shots.map((s,i)=>`${i+1}. ${s.title} (${s.duration}s)\n\nIMAGE PROMPT (${extensions.visible(s,'image').lang})\n${extensions.visible(s,'image').text}\n\nVIDEO PROMPT (${extensions.visible(s,'video').lang})\n${extensions.visible(s,'video').text}`).join('\n\n--------------------------------\n\n');}
function printSheet(){if(!readySheet())return;const host=$('printArea');host.replaceChildren(node('h1',state.title||'Scene DNA'),node('p','ArtofTomworks Scene DNA '+VERSION+' · '+state.aspect));for(const [index,s]of state.shots.entries()){const card=node('article');card.append(node('h2',(index+1)+'. '+s.title+' · '+s.duration+'s'));if(s.result||state.reference){const img=node('img');img.src=(s.result||state.reference).data;img.alt=s.title;card.append(img);}for(const kind of ['image','video'])card.append(node('h3',t(kind+'Prompt')+' · '+extensions.visible(s,kind).lang),node('pre',extensions.visible(s,kind).text));host.append(card);}window.print();}
