async function initStorage(){const initialId=state.id,initialUpdated=state.updated;try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('artoftomworks.scene-dna',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});const saved=await new Promise((resolve,reject)=>{const req=db.transaction('projects').objectStore('projects').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(state.id===initialId&&state.updated===initialUpdated&&saved){const candidate=validateProject(saved);if(candidate.updated>=state.updated){state=candidate;status('saved');return;}}if(state.title||state.shots.length)status('storageFallback');}catch{status('saveFail');}}
